// Convert electricity + fuel consumption into estimated CO2e emissions, split by GHG Protocol scope
const apiResponse = $input.item.json;
const config = $('Set - Config').item.json;

// Prefer the live grid factor from the API (gCO2/kWh -> kgCO2/kWh), fall back to config default
let gridFactorKgPerKwh = parseFloat(config.electricityEmissionFactorFallback);
try {
  const gco2PerKwh = apiResponse?.data?.[0]?.intensity?.actual
    ?? apiResponse?.data?.[0]?.intensity?.forecast
    ?? apiResponse?.intensity?.actual
    ?? apiResponse?.intensity?.forecast
    ?? null;
  if (gco2PerKwh !== null && gco2PerKwh !== undefined) {
    gridFactorKgPerKwh = Number(gco2PerKwh) / 1000;
  }
} catch (e) {
  // keep fallback factor
}

const electricityKwh = Number(config.electricityKwh || 0);
const electricityEmissionsKg = +(electricityKwh * gridFactorKgPerKwh).toFixed(2);

let fuelConsumption = [];
let fuelFactors = {};
let scopeMapping = {};
try { fuelConsumption = JSON.parse(config.fuelConsumptionJson || '[]'); } catch (e) { fuelConsumption = []; }
try { fuelFactors = JSON.parse(config.fuelEmissionFactorsJson || '{}'); } catch (e) { fuelFactors = {}; }
try { scopeMapping = JSON.parse(config.scopeMappingJson || '{}'); } catch (e) { scopeMapping = {}; }

let fuelEmissionsKg = 0;
const fuelBreakdown = [];
for (const entry of fuelConsumption) {
  const factor = Number(fuelFactors[entry.type] || 0);
  const emissions = +(Number(entry.amount || 0) * factor).toFixed(2);
  fuelEmissionsKg += emissions;
  fuelBreakdown.push({ type: entry.type, amount: entry.amount, unit: entry.unit, emissionFactorKgPerUnit: factor, emissionsKg: emissions, scope: scopeMapping[entry.type] || 'scope1' });
}
fuelEmissionsKg = +fuelEmissionsKg.toFixed(2);

const totalEmissionsKg = +(electricityEmissionsKg + fuelEmissionsKg).toFixed(2);

// GHG Protocol scope split: Scope 1 = direct fuel combustion, Scope 2 = purchased electricity
const scope1EmissionsKg = fuelEmissionsKg;
const scope2EmissionsKg = electricityEmissionsKg;
const scope1PercentOfTotal = totalEmissionsKg > 0 ? +((scope1EmissionsKg / totalEmissionsKg) * 100).toFixed(1) : 0;
const scope2PercentOfTotal = totalEmissionsKg > 0 ? +((scope2EmissionsKg / totalEmissionsKg) * 100).toFixed(1) : 0;

let emissionCategory = 'low';
if (totalEmissionsKg >= Number(config.criticalThresholdKg)) emissionCategory = 'critical';
else if (totalEmissionsKg >= Number(config.highThresholdKg)) emissionCategory = 'high';
else if (totalEmissionsKg >= Number(config.mediumThresholdKg)) emissionCategory = 'medium';

return {
  json: {
    ...config,
    gridFactorKgPerKwh,
    electricityKwh,
    electricityEmissionsKg,
    fuelBreakdown,
    fuelEmissionsKg,
    totalEmissionsKg,
    scope1EmissionsKg,
    scope2EmissionsKg,
    scope1PercentOfTotal,
    scope2PercentOfTotal,
    emissionCategory
  }
};

// Compare current total emissions against the prior period fetched from the ESG dashboard.
// If the optional HTTP Request - Fetch Prior Period Report node isn't connected, this just
// passes through with trendAvailable: false so the LLM prompt handles it gracefully.
const current = $('JS - Calculate Carbon Emissions').item.json;

let priorTotalKg = null;
try {
  const priorNode = $('HTTP Request - Fetch Prior Period Report (optional)');
  const priorJson = priorNode?.item?.json;
  priorTotalKg = priorJson?.totalEmissionsKg ?? priorJson?.total_emissions_kg ?? null;
} catch (e) {
  priorTotalKg = null;
}

let trendAvailable = false;
let percentChange = null;
let trendDirection = 'unknown';

if (priorTotalKg !== null && priorTotalKg !== undefined && Number(priorTotalKg) > 0) {
  trendAvailable = true;
  percentChange = +(((current.totalEmissionsKg - Number(priorTotalKg)) / Number(priorTotalKg)) * 100).toFixed(1);
  trendDirection = percentChange > 0 ? 'increase' : (percentChange < 0 ? 'decrease' : 'flat');
}

return {
  json: {
    ...current,
    priorTotalKg,
    trendAvailable,
    percentChange,
    trendDirection
  }
};

const item = $input.item.json;
const tonnesCo2e = +(item.totalEmissionsKg / 1000).toFixed(3);
const pricePerTonne = Number(item.offsetPricePerTonneUsd || 0);
const estimatedOffsetCostUsd = +(tonnesCo2e * pricePerTonne).toFixed(2);

return {
  json: {
    ...item,
    tonnesCo2e,
    estimatedOffsetCostUsd
  }
};

