Trend vs prior period: {{ $('JS - Estimate Offset Cost (optional)').item.json.trendAvailable ? ($('JS - Estimate Offset Cost (optional)').item.json.percentChange + '% ' + $('JS - Estimate Offset Cost (optional)').item.json.trendDirection + ' vs prior total of ' + $('JS - Estimate Offset Cost (optional)').item.json.priorTotalKg + ' kg CO2e') : 'no prior period data available' }}

