// Parse the LLM's structured report JSON, falling back to a plain-numbers summary if needed
const item = $input.item.json;
const raw = item.text || item.output || item.response || '{}';
const calc = $('JS - Estimate Offset Cost (optional)').item.json;

let parsed = {};
try {
  const cleaned = String(raw).replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    reportTitle: `${calc.facilityName} - Carbon Emissions Report`,
    executiveSummary: `Total emissions for the period were ${calc.totalEmissionsKg} kg CO2e (category: ${calc.emissionCategory}). Scope 1 (fuel): ${calc.scope1EmissionsKg} kg CO2e, Scope 2 (electricity): ${calc.scope2EmissionsKg} kg CO2e.`,
    keyMetrics: [
      `Scope 1: ${calc.scope1EmissionsKg} kg CO2e (${calc.scope1PercentOfTotal}%)`,
      `Scope 2: ${calc.scope2EmissionsKg} kg CO2e (${calc.scope2PercentOfTotal}%)`,
      `Total: ${calc.totalEmissionsKg} kg CO2e`,
      `Estimated offset cost: $${calc.estimatedOffsetCostUsd} (${calc.tonnesCo2e} tonnes)`
    ],
    recommendations: [],
    trend: calc.trendAvailable ? `${calc.percentChange}% ${calc.trendDirection} vs prior period` : 'No prior period data available for trend comparison.',
    tags: [calc.emissionCategory]
  };
}

return {
  json: {
    ...calc,
    reportTitle: parsed.reportTitle || `${calc.facilityName} - Carbon Emissions Report`,
    executiveSummary: parsed.executiveSummary || '',
    keyMetrics: parsed.keyMetrics || [],
    recommendations: parsed.recommendations || [],
    trend: parsed.trend || '',
    tags: parsed.tags || [],
    generatedAt: new Date().toISOString()
  }
};

